typedef float vm_num_t;

class stringx;
class vm_executable { public: const stringx& get_fullname() const; };
class script_object { public: class instance { public: const stringx& get_name() const; }; };
class vm_thread { public: script_object::instance* get_instance() const; const vm_executable* get_executable() const; };
class stringx {};
stringx operator+(const stringx&, const char*);
stringx operator+(const stringx&, const stringx&);
void error(const stringx&);

class vm_stack {
public:
  int salloc;
  char* buffer;
  char* SP;
private:
  vm_thread* my_thread;
public:
  bool push(const char* src, int n);
  vm_thread* get_thread() const { return my_thread; }
};

class script_library_class {
public:
  class function {
  public:
    enum entry_t { FIRST_ENTRY, RECALL_ENTRY };
    function() {}
    virtual ~function();
    virtual bool operator()(vm_stack&, entry_t) { return true; }
  };
};

class game { public: bool was_A_pressed() const; };
class app { public: static app* inst(); game* get_game(); };

#define SLF_RETURN \
  if (!stack.push((char*)&result,sizeof(result)) ) \
    error( stack.get_thread()->get_instance()->get_name() + ": stack overflow in " + stack.get_thread()->get_executable()->get_fullname() )
#define SLF_DONE return true

class slf_was_A_pressed_t : public script_library_class::function
{
  public:
    // constructor required
    slf_was_A_pressed_t(const char* n): script_library_class::function() { }
    // library function execution
    virtual bool operator ()(vm_stack &stack, entry_t entry)
    {
      vm_num_t result = app::inst()->get_game()->was_A_pressed();
      SLF_RETURN;
      SLF_DONE;
    }
};
